input.command:
S=$(mktemp -d) && git status --porcelain > $S/before; md5 -q .dev-graph/state/graph.json;
python3 plugins/dev-graph/scripts/diff-github-issues.py --repo-root . > $S/i.json; echo rc=$?; python3 plugins/dev-graph/scripts/diff-github-project-fields.py --repo-root . --issue-plan .dev-graph/cache/sync-run2/issue-plan-1.json > $S/p.json; echo rc=$?;
python3 -c "
import json,sys
for a,b in [('$S/i.json','.dev-graph/cache/sync-run2/issue-plan-1.json'),('$S/p.json','.dev-graph/cache/sync-run2/project-plan-1.json')]:
  x=json.load(open(a)); y=json.load(open(b)); print(a.split('/')[-1], 'identical' if x==y else 'DIFF', {k:x.get(k) for k in ['changes','converged','unresolved_count','graph_revision','next']})
"
git status --porcelain > $S/after; diff $S/before $S/after && echo no-worktree-change; md5 -q .dev-graph/state/graph.json; tail -3 github-adapter-calls.jsonl | cut -c1-200

